public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        int N = Integer.parseInt(br.readLine());
        long[] L = new long[N];
        StringTokenizer st = new StringTokenizer(br.readLine());
        long total = 0;
        for (int i = 0; i < N; i++) {
            L[i] = Long.parseLong(st.nextToken());
            total += L[i];
        }

        long lo = 0, hi = total;
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (canSplit(L, mid)) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        System.out.println(lo);
    }

    static boolean canSplit(long[] L, long maxDiff) {
        int n = L.length;
        // Try all possible min lengths by choosing a starting piece
        // Since lengths are positive, the minimum piece length will be one of the prefix sums or piece lengths.
        // We'll do two-pointer sliding window check.

        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + L[i];
        }

        // For each possible left bound (start of a piece), try to see if we can cover the whole array
        // with each piece length in [minLen, minLen + maxDiff].

        // Instead of trying all minLen, we can binary search or use a two-pointer feasibility approach.
        // We'll use a DP-like check: can we partition such that each piece length is between low and low+maxDiff?

        // We can binary search on low (minimum piece length).
        long lo = 1, hi = prefix[n];
        while (lo <= hi) {
            long minLen = lo + (hi - lo) / 2;
            if (canPartitionWithMinLen(prefix, minLen, maxDiff)) {
                lo = minLen + 1;
            } else {
                hi = minLen - 1;
            }
        }
        // If there exists some minLen that works, return true.
        // We check if hi is valid:
        return hi >= 1 && canPartitionWithMinLen(prefix, hi, maxDiff);
    }

    static boolean canPartitionWithMinLen(long[] prefix, long minLen, long maxDiff) {
        long maxLen = minLen + maxDiff;
        int n = prefix.length - 1;

        // DP: dp[i] = true if first i elements can be partitioned
        boolean[] dp = new boolean[n + 1];
        dp[0] = true;

        // Use two-pointer to speed up
        int left = 0;
        for (int i = 1; i <= n; i++) {
            // Find leftmost start such that piece length >= minLen
            while (left < i && prefix[i] - prefix[left] > maxLen) {
                left++;
            }
            // Check if any valid start exists with length in [minLen, maxLen]
            int start = left;
            while (start < i && prefix[i] - prefix[start] >= minLen) {
                if (dp[start]) {
                    dp[i] = true;
                    break;
                }
                start++;
            }
        }
        return dp[n];
    }
}

