import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static int N;
    static long[] L;
    static long[] prefix;
    static long total;

    static boolean can(long d) {
        for (int s = 0; s < N; s++) {
            long minLen = L[s];
            long maxLen = minLen + d;
            if (maxLen < minLen) continue;

            long pos = prefix[s];
            int idx = s + 1;

            while (true) {
                if (total - pos >= minLen && total - pos <= maxLen) return true;

                long need = pos + minLen;
                long limit = pos + maxLen;

                while (idx < N && prefix[idx] < need) idx++;
                if (idx >= N || prefix[idx] > limit) break;

                pos = prefix[idx];
                idx++;
            }
        }
        return false;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        N = fs.nextInt();
        L = new long[N];
        prefix = new long[N + 1];
        for (int i = 0; i < N; i++) {
            L[i] = fs.nextLong();
            prefix[i + 1] = prefix[i] + L[i];
        }
        total = prefix[N];

        long low = 0, high = total;
        while (low < high) {
            long mid = (low + high) >>> 1;
            if (can(mid)) high = mid;
            else low = mid + 1;
        }

        System.out.println(low);
    }
